def roof(w,d,eave,rise):
    # Four overlapping thick courses; irregular straw ends shape the silhouette.
    for side in [-1,1]:
        for row in range(4):
            t0=row/4;t1=min(1,(row+1)/4+.07)
            n=max(12,int(d/.18));vs=[]
