                    xx=side*w*.5*t
                    zz=eave+rise*(1-t)
                    if edge:zz+=.027*math.sin(j*2.4+row)
                    vs.append((xx,yy,zz+.045*(3-row)))
            fs=[]
            for j in range(n):fs.append((j,j+1,n+2+j,n+1+j) if side>0 else (j,n+1+j,n+2+j,j+1))
            o=mesh('Hut_ThatchedCourse',vs,fs,M[['ThatchLight','Thatch','Thatch','ThatchDark'][row]],1)
            mod=o.modifiers.new('Bundled straw thickness','SOLIDIFY');mod.thickness=.10
    beam('Hut_RidgeCap',(0,-d*.5-.06,eave+rise+.10),(0,d*.5+.06,eave+rise+.10),.14,M['Beam'])
